// 16x16 toroid (periodic) game of life
module TopModule(
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);
    reg [255:0] r;
    wire [255:0] next;
    genvar x, y;
    // Neighbour count (self not counted)
    function [7:0] count(reg [255:0] v, int x, int y);
        reg [7:0] c = 0;
        for (int dx = -1; dx <= 1; dx += 1)
            for (int dy = -1; dy <= 1; dy += 1)
                c += v[16*((y+dy)%16) + 16*((x+dx)%16)];
        return c - v[16*y + 16*x];
    endfunction
    // Next state (register combinatorial)
    for (x = 0; x < 16; x = x + 1)
        for (y = 0; y < 16; y = y + 1)
            always @* begin
                next[16*y + x] = r[16*y + x]
                    ? (count(r, x, y) < 2 || 4 <= count(r, x, y))
                    : (count(r, x, y) == 3);
            end
    // Register chain (1 clock latency per stage)
    always @(posedge clk) r <= next;
    // Load (1 clock latency)
    always @(posedge clk) if (load) r <= data;
    // Output the final register chain (0 latency)
    assign q = r;
endmodule

