// A 16x16 toroid, as described in the docstring.
module Toroid16x16(input [15:0] q [0:15], output [15:0] n [0:15]);
  genvar i, j;
  for (i = 0; i < 16; i = i + 1) begin
    for (j = 0; j < 16; j = j + 1) begin
      // Neighbour indices, wrapped to the toroid (periodic boundary
      // conditions).
      wire [15:0] ns [0:7] = '{q[(i-1)%16][(j-1)%16], q[(i-1)%16][j], q[(i-1)%16][(j+1)%16],
                            q[i][(j-1)%16],                   q[i][(j+1)%16],
                            q[(i+1)%16][(j-1)%16], q[(i+1)%16][j], q[(i+1)%16][(j+1)%16]};
      // Number of live neighbours.
      wire [3:0] n_live = 4'b0 + ns[0] + ns[1] + ns[2] + ns[3] + ns[4] + ns[5] + ns[6] + ns[7];
      // Cell next state.
      assign n[i][j] = (q[i][j] && (n_live == 3 || n_live == 4)) || (!q[i][j] && n_live == 3);
    end
  end
endmodule

