// 16x16 toroid game, as described in the problem description. Implemented as
// an EDGE-triggered combinational function: the game state at the next clock
// edge depends only on the current state (reg q) and the input data, and not
// on any previous states.
module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] nxtq;
    integer i, j;
    reg [7:0] n;
    always @(*) begin
        for (i = 0; i < 16; i = i + 1)
            for (j = 0; j < 16; j = j + 1) begin
                n = data[16*((i + 16 - 1) % 16) + (j + 16 - 1) % 16]
                  + data[16*((i + 16 - 1) % 16) + (j + 16 + 1) % 16]
                  + data[16*((i + 16 + 1) % 16) + (j + 16 - 1) % 16]
                  + data[16*((i + 16 + 1) % 16) + (j + 16 + 1) % 16]
                  + data[16*((i + 16 - 1) % 16) + (j + 16) % 16]
                  + data[16*((i + 16 + 1) % 16) + (j + 16) % 16]
                  + data[16*(i + 16) + (j + 16 - 1) % 16]
                  + data[16*(i + 16) + (j + 16 + 1) % 16];
